# EoH heuristic generated by this code
import numpy as np

def score(item: int, bins: np.ndarray) -> np.ndarray:

    bins_f = bins.astype(float)
    n = bins_f.size
    if n == 0:
        return bins_f

    remaining = bins_f - float(item)

    # Tight fit: prefer bins that leave little slack.
    tight = 1.0 / (1.0 + remaining)

    # Centrality over the current feasible residual band: favor stable mid-range leftovers.
    lo = np.min(remaining)
    hi = np.max(remaining)
    span = max(hi - lo, 1.0)
    center = 1.0 - np.abs((remaining - lo) / span - 0.5) * 2.0

    # Fragmentation penalty: discourage leftovers that are too common or too extreme.
    if n == 1:
        frag = np.ones_like(remaining)
    else:
        sorted_res = np.sort(remaining)
        q1 = sorted_res[int(0.25 * (n - 1))]
        q3 = sorted_res[int(0.75 * (n - 1))]
        iqr = max(q3 - q1, 1.0)
        dist_to_band = np.abs(remaining - 0.5 * (q1 + q3)) / iqr
        frag = 1.0 / (1.0 + dist_to_band)

    # Slight preference for larger original bins when scores are otherwise close.
    bin_span = max(np.max(bins_f) - np.min(bins_f), 1.0)
    size_bias = (bins_f - np.min(bins_f)) / bin_span

    scores = 0.44 * tight + 0.34 * center + 0.16 * frag + 0.06 * size_bias
    return scores
    